package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.*;
/** Run prepare and verify in different app processes, with force-stop between. */
public class ProcessRecoveryTest extends Instrumentation {
    String phase;public void onCreate(Bundle b){super.onCreate(b);phase=b.getString("phase","verify");start();}
    public void onStart(){Bundle result=new Bundle();MainActivity a=null;boolean passed=false;String id="process_recovery_qa";File file=new File(getTargetContext().getFilesDir(),"book_"+id+".txt");try{
        if("prepare".equals(phase)){StringBuilder source=new StringBuilder();for(int n=1;n<=3;n++){source.append("第").append(n).append("章 风与书\n");for(int i=0;i<30;i++)source.append("书页轻轻翻动，风从窗边吹过。\n");}String text=source.toString();try(FileOutputStream out=new FileOutputStream(file)){out.write(text.getBytes(StandardCharsets.UTF_8));}int position=MainActivity.parse(text).get(1).start+130;ReadingCheckpoint.write(new File(file+".position"),file.getName(),text,position,1000);getTargetContext().getSharedPreferences("reader_"+id,0).edit().putInt("position",0).putLong("checkpointVersion",0).putInt("qaExpected",position).commit();result.putString("result","PREPARED: durable checkpoint with stale preferences");passed=true;
        }else{a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id",id).putExtra("book_name","恢复验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity reader=a;long end=SystemClock.elapsedRealtime()+30000;AtomicBoolean loaded=new AtomicBoolean();while(SystemClock.elapsedRealtime()<end){runOnMainSync(()->loaded.set(!reader.text.isEmpty()));if(loaded.get())break;Thread.sleep(50);}int expected=getTargetContext().getSharedPreferences("reader_"+id,0).getInt("qaExpected",-1);AtomicBoolean correct=new AtomicBoolean();runOnMainSync(()->correct.set(reader.position==expected&&reader.chapter==1&&!reader.playing));if(!correct.get())throw new AssertionError("Fresh process did not restore checkpoint: "+reader.position+" expected "+expected);result.putString("result","PASS: fresh app process restored chapter and exact saved source offset from atomic checkpoint; no autoplay");passed=true;}
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(a!=null){final MainActivity reader=a;runOnMainSync(()->{reader.stop();reader.finish();});waitForIdleSync();}if(!"prepare".equals(phase)){file.delete();new File(file+".position").delete();getTargetContext().getSharedPreferences("reader_"+id,0).edit().clear().commit();}}finish(passed?-1:0,result);}
}
